WITH "r0" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND ( ( true AND ( EXISTS (SELECT 1 FROM "public"."author" AS "e0" WHERE true AND "e0"."id" = "s"."author_id" AND ( ( true AND ( "e0"."id" <= $1 ) AND ( "e0"."id" >= $2 ) ) )) ) AND ( "s"."id" <= $3 ) ) ) ORDER BY "s"."id" ASC NULLS LAST ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0"
